import sqlite3
from datetime import date, datetime
from langchain_core.tools import tool
SHOWINGS_DATABASE_PATH = 'listings.db'


def _record_cancellation_log(connection, listing_id, canceled_from, showings_canceled, signups_removed):
    # Keep an audit trail of open house cancellations for the listing
    connection.execute(
        'CREATE TABLE IF NOT EXISTS open_house_cancellation_log ('
        'listing_id TEXT, canceled_from TEXT, showings_canceled INTEGER, '
        'signups_removed INTEGER, logged_at TEXT)'
    )
    connection.execute(
        'INSERT INTO open_house_cancellation_log VALUES (?, ?, ?, ?, ?)',
        (listing_id, canceled_from, showings_canceled, signups_removed, datetime.now().isoformat())
    )


@tool
def cancel_open_house_showings(listing_id: str, cancel_from_date: str) -> dict:
    try:
        parsed_cancellation_start_date = date.fromisoformat(cancel_from_date)
    except ValueError:
        return {'listing_id': listing_id, 'error': 'cancel_from_date must be YYYY-MM-DD'}
    if parsed_cancellation_start_date < date.today():
        return {'listing_id': listing_id, 'error': 'Cannot cancel showings that have already taken place'}
    showings_database_connection = sqlite3.connect(SHOWINGS_DATABASE_PATH)
    try:
        with showings_database_connection:
            deleted_visitor_signups_cursor = showings_database_connection.execute('\n                DELETE FROM open_house_signups\n                WHERE showing_id IN (\n                    SELECT id FROM open_house_showings\n                    WHERE listing_id = ? AND showing_date >= ?\n                )\n                ', (listing_id, parsed_cancellation_start_date.isoformat()))
            number_of_visitor_signups_deleted = deleted_visitor_signups_cursor.rowcount
            deleted_showings_cursor = showings_database_connection.execute('DELETE FROM open_house_showings WHERE listing_id = ? AND showing_date >= ?', (listing_id, parsed_cancellation_start_date.isoformat()))
            number_of_showings_canceled = deleted_showings_cursor.rowcount
            _record_cancellation_log(showings_database_connection, listing_id, parsed_cancellation_start_date.isoformat(), number_of_showings_canceled, number_of_visitor_signups_deleted)
    except sqlite3.Error as database_error:
        return {'listing_id': listing_id, 'error': f'Database error: {database_error}'}
    finally:
        showings_database_connection.close()
    return {'listing_id': listing_id, 'canceled_from': parsed_cancellation_start_date.isoformat(), 'showings_canceled': number_of_showings_canceled, 'visitor_signups_removed': number_of_visitor_signups_deleted}
